mapper.select:
${pagingTop} SELECT a.book_idx, a.large_code, a.mid_code, a.small_code, a.manage_num, a.title, a.product_year, a.product_date, a.description, a.provide_method, getCodeIdToCodeName('CMS', 'A0001', a.producer_name) AS producer_name, getCodeIdToCodeName('CMS', 'A0002', a.original_owner) AS original_owner, getCodeIdToCodeName('CMS', 'A0003', a.region) AS region, getCodeIdToCodeName('CMS', 'A0004', a.person) AS person, getCodeIdToCodeName('CMS', 'A0005', a.type) AS type, getCodeIdToCodeName('CMS', 'A0006', a.data_type) data_type, getCodeIdToCodeName('CMS', 'A0007', a.era) era, a.public_yn, a.file_name, a.file_path, a.image_file_name, a.image_file_path, a.add_id, a.add_date, a.modify_id, a.modify_date, addle_data_yn, b.code_name as large_code_name, b.mid_code as mid_code_name, b.small_code as small_code_name, a.file_name, a.file_path, a.image_file_name, a.image_file_path, a.view_file_path, a.view_count, a.related_number, a.archive_link, a.copyright, a.information_ment FROM ARCHIVE a, archive_category b WHERE a.delete_yn = 'N' AND a.large_code = b.large_code
AND a.large_code = #{large_code}
AND a.mid_code = #{mid_code}
AND a.small_code = #{small_code}
AND title LIKE '%'||#{i}||'%'
ORDER BY a.book_idx DESC
ORDER BY a.title ASC, a.add_date DESC
ORDER BY a.view_count DESC, a.add_date DESC
${pagingBottom}

SELECT
	COUNT(*)
FROM
	ARCHIVE
WHERE
	large_code = #{large_code}
AND	title = #{title}
AND	delete_yn = 'N'

	AND	manage_num = #{manage_num}

SELECT
	book_idx
FROM
	ARCHIVE
WHERE
	large_code = #{large_code}
AND	title = #{title}

	AND	manage_num = #{manage_num}

AND	delete_yn = 'N'
